import { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

function AuthPage() {

    const navigate = useNavigate();

    const [mode, setMode] = useState('login');

    // LOGIN STATES
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    // SIGNUP STATES
    const [signupName, setSignupName] = useState('');
    const [signupEmail, setSignupEmail] = useState('');
    const [signupPassword, setSignupPassword] = useState('');
    const [signupMobile, setSignupMobile] = useState('');

    // =========================
    // LOGIN FUNCTION
    // =========================

    const handleLogin = async () => {

        try {

            const response = await axios.post(

                'http://localhost:5000/auth/login',

                {
                    email,
                    password
                }

            );

            // SAVE TOKEN

            localStorage.setItem(
                'token',
                response.data.token
            );

            // SAVE USER

            localStorage.setItem(
                'user',
                JSON.stringify(response.data.user)
            );

            alert('Login Successful');

            navigate('/dashboard');

        } catch (error) {

            alert(
                error.response?.data?.message ||
                'Login Failed'
            );

        }

    };

    // =========================
    // SIGNUP FUNCTION
    // =========================

    const handleSignup = async () => {

        try {

            await axios.post(

                'http://localhost:5000/auth/signup',

                {
                    name: signupName,
                    email: signupEmail,
                    password: signupPassword,
                    mobileNumber: signupMobile
                }

            );

            alert('Account Created Successfully');

            setMode('login');

        } catch (error) {

            alert(
                error.response?.data?.message ||
                'Signup Failed'
            );

        }

    };

    return (

        <div className="min-h-screen flex bg-surface text-on-surface font-inter relative overflow-hidden">

            {/* LEFT SIDE */}

            <div className="
                hidden
                lg:flex
                w-1/2
                relative
                overflow-hidden
                flex-col
                justify-between
                p-16
            ">

                {/* Background gradient */}
                <div className="absolute inset-0 bg-gradient-to-br from-surface via-surface-container-lowest to-[#1e1b4b]" />

                {/* GLOW ORBS */}
                <div className="absolute w-96 h-96 bg-vibrant-violet/20 rounded-full blur-[120px] top-[-100px] left-[-100px] animate-pulse-glow" />
                <div className="absolute bottom-[-120px] right-[-120px] w-[400px] h-[400px] bg-electric-blue/15 rounded-full blur-[120px] animate-float" />

                {/* LOGO */}
                <div className="relative z-10">
                    <div className="flex items-center gap-4">
                        <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center text-2xl shadow-lg">
                            ⚡
                        </div>
                        <div>
                            <h1 className="text-headline-lg text-on-surface">
                                WattWise
                            </h1>
                            <p className="text-on-surface-variant text-body-md mt-0.5">
                                Smart Energy Intelligence
                            </p>
                        </div>
                    </div>
                </div>

                {/* CENTER */}
                <div className="relative z-10">

                    <h1 className="text-display-lg leading-tight max-w-2xl">
                        <span className="gradient-text">Monitor.</span>
                        <br />
                        <span className="text-on-surface">Analyze.</span>
                        <br />
                        <span className="gradient-text">Optimize.</span>
                    </h1>

                    <p className="text-xl text-on-surface-variant mt-8 max-w-xl leading-relaxed">
                        AI-powered platform for intelligent energy monitoring,
                        live analytics, cost optimization, and real-time alerts.
                    </p>

                    {/* FEATURE CARDS */}
                    <div className="grid grid-cols-2 gap-4 mt-12">

                        {[
                            { icon: 'bolt', title: 'Live Monitoring', desc: 'Real-time power tracking', color: 'electric-blue' },
                            { icon: 'analytics', title: 'Smart Analytics', desc: 'Advanced energy insights', color: 'vibrant-violet' },
                            { icon: 'shield', title: 'Secure Platform', desc: 'Protected user data', color: 'primary' },
                            { icon: 'warning', title: 'Smart Alerts', desc: 'Instant anomaly detection', color: 'error-red' },
                        ].map((item, i) => (
                            <div key={i} className="glass-card-subtle p-5 group">
                                <div className={`w-10 h-10 rounded-lg bg-${item.color}/20 text-${item.color} flex items-center justify-center mb-3 border border-${item.color}/20`}>
                                    <span className="material-symbols-outlined text-[20px]">
                                        {item.icon}
                                    </span>
                                </div>
                                <h3 className="text-body-md font-semibold text-on-surface">{item.title}</h3>
                                <p className="text-on-surface-variant text-[13px] mt-1">{item.desc}</p>
                            </div>
                        ))}

                    </div>

                </div>

                {/* FOOTER */}
                <div className="relative z-10 text-on-surface-variant/50 text-body-md">
                    © 2026 WattWise. All rights reserved.
                </div>

            </div>

            {/* RIGHT SIDE */}

            <div className="
                w-full
                lg:w-1/2
                flex
                items-center
                justify-center
                p-6
            ">

                <div className="
                    w-full
                    max-w-md
                    glass-card
                    p-10
                    shadow-2xl
                ">

                    {/* MOBILE LOGO */}
                    <div className="lg:hidden text-center mb-10">
                        <div className="w-14 h-14 mx-auto rounded-2xl bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center text-2xl shadow-lg">
                            ⚡
                        </div>
                        <h1 className="text-headline-lg mt-5 text-on-surface">
                            WattWise
                        </h1>
                    </div>

                    {/* TOGGLE */}

                    {mode !== 'forgot' && (

                        <div className="flex bg-surface-container-lowest rounded-xl p-1.5 mb-8">

                            <button
                                onClick={() => setMode('login')}
                                className={`
                                    flex-1
                                    py-3
                                    rounded-lg
                                    font-semibold
                                    transition-all duration-300
                                    text-body-md
                                    ${mode === 'login'
                                        ? 'bg-vibrant-violet text-white glow-violet'
                                        : 'text-on-surface-variant hover:text-on-surface'}
                                `}
                            >
                                Login
                            </button>

                            <button
                                onClick={() => setMode('signup')}
                                className={`
                                    flex-1
                                    py-3
                                    rounded-lg
                                    font-semibold
                                    transition-all duration-300
                                    text-body-md
                                    ${mode === 'signup'
                                        ? 'bg-vibrant-violet text-white glow-violet'
                                        : 'text-on-surface-variant hover:text-on-surface'}
                                `}
                            >
                                Signup
                            </button>

                        </div>

                    )}

                    {/* LOGIN */}

                    {mode === 'login' && (

                        <div>

                            <h2 className="text-headline-lg text-on-surface mb-2">
                                Welcome Back
                            </h2>

                            <p className="text-on-surface-variant text-body-md mb-8">
                                Login to your WattWise account
                            </p>

                            <div className="space-y-5">

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Email
                                    </label>
                                    <input
                                        type="email"
                                        placeholder="you@example.com"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        className="glass-input"
                                    />
                                </div>

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Password
                                    </label>
                                    <input
                                        type="password"
                                        placeholder="••••••••"
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        className="glass-input"
                                    />
                                </div>

                                <button
                                    onClick={handleLogin}
                                    className="btn-primary w-full py-4 text-lg rounded-xl"
                                >
                                    Login
                                </button>

                            </div>

                            <button
                                onClick={() => setMode('forgot')}
                                className="text-vibrant-violet mt-6 text-sm hover:underline"
                            >
                                Forgot Password?
                            </button>

                        </div>

                    )}

                    {/* SIGNUP */}

                    {mode === 'signup' && (

                        <div>

                            <h2 className="text-headline-lg text-on-surface mb-2">
                                Create Account
                            </h2>

                            <p className="text-on-surface-variant text-body-md mb-8">
                                Start using WattWise today
                            </p>

                            <div className="space-y-4">

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Full Name
                                    </label>
                                    <input
                                        type="text"
                                        placeholder="John Doe"
                                        value={signupName}
                                        onChange={(e) => setSignupName(e.target.value)}
                                        className="glass-input"
                                    />
                                </div>

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Email
                                    </label>
                                    <input
                                        type="email"
                                        placeholder="you@example.com"
                                        value={signupEmail}
                                        onChange={(e) => setSignupEmail(e.target.value)}
                                        className="glass-input"
                                    />
                                </div>

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Mobile Number
                                    </label>
                                    <input
                                        type="tel"
                                        placeholder="+15551234567"
                                        value={signupMobile}
                                        onChange={(e) => setSignupMobile(e.target.value)}
                                        className="glass-input"
                                    />
                                    <p className="text-on-surface-variant/50 text-[11px] mt-2">
                                        Used for SMS alerts when devices exceed power limits.
                                    </p>
                                </div>

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Password
                                    </label>
                                    <input
                                        type="password"
                                        placeholder="••••••••"
                                        value={signupPassword}
                                        onChange={(e) => setSignupPassword(e.target.value)}
                                        className="glass-input"
                                    />
                                </div>

                                <button
                                    onClick={handleSignup}
                                    className="btn-primary w-full py-4 text-lg rounded-xl"
                                >
                                    Create Account
                                </button>

                            </div>

                        </div>

                    )}

                    {/* FORGOT */}

                    {mode === 'forgot' && (

                        <div>

                            <h2 className="text-headline-lg text-on-surface mb-2">
                                Reset Password
                            </h2>

                            <p className="text-on-surface-variant text-body-md mb-8">
                                Enter your email to continue
                            </p>

                            <div className="space-y-5">

                                <div>
                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                        Email
                                    </label>
                                    <input
                                        type="email"
                                        placeholder="you@example.com"
                                        className="glass-input"
                                    />
                                </div>

                                <button
                                    className="btn-primary w-full py-4 text-lg rounded-xl"
                                >
                                    Send Reset Link
                                </button>

                            </div>

                            <button
                                onClick={() => setMode('login')}
                                className="text-vibrant-violet mt-6 text-sm hover:underline"
                            >
                                Back to Login
                            </button>

                        </div>

                    )}

                </div>

            </div>

        </div>

    );

}

export default AuthPage;
